import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data'
def read(c):return json.loads((p/(c+'.json')).read_text())
def write(c,d):(p/(c+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2))
def add(c,name,slug,url,rid,date,fields,version='браузерная социальная версия; конкретная сеть не уточнена',create=False):
 d=read(c);e=next((x for x in d if x['name'].lower()==name.lower()),None)
 if not e and not create:print('not found',name);return
 if not e:
  e=dict(slug=slug,name=name,category=c,type={'locations':'Острова','buildings':'Постройки','updates':'История обновлений'}[c],purchase='нет данных',sale='нет данных',obtain='нет данных',use='нет данных',features='нет данных',versions=version,sources=[],image=None,links=[],event='нет данных',prior_records=[]);d.append(e)
 e.setdefault('prior_records',[]);e['prior_records']=[r for r in e['prior_records'] if r.get('original_id')!=rid]+[dict(original_id=rid,original_category='Историческая публикация',version=version,date=date,fields=fields,confidence='Историческая фанатская публикация; возможно, воспроизводит иной первоисточник. Актуальность и независимость не подтверждены.')]
 if not any(s['url']==url for s in e['sources']):e['sources'].append(dict(url=url,label='Прочитана историческая страница'))
 write(c,d)
u='https://zombi-ferma.ucoz.net/news/zombi_ferma_khehllouin_na_vsekh_fermakh/2017-10-29-218'
add('locations','Призрачная Ярмарка','prizrachnaya-yarmarka-2017',u,'zombi-ferma-2017-yarmarka','29.10.2017',{'Событие':'Временный остров доступен 14 дней с первого посещения; после спасения Упырёши закрывается навсегда.','Квесты':'Согласно статье, для спасения необходимо 14 заданий; диалоги и условия не опубликованы в новости.','На острове':'Летают привидения; в сокровищах может быть Пунш.'},create=True)
add('buildings','Чертово колесо','chertovo-koleso-2017',u,'zombi-ferma-2017-koleso','29.10.2017',{'Постройка':'На рынке; пять стадий; после достройки превращается в гору подарков.','Пунш':'Можно настучать под Колесом у друзей, выбить из привидений или найти в сокровищах Призрачной Ярмарки. Количество и стадии новость не уточняет.'},create=True)
add('buildings','Зомби-вертикаль','', 'https://social-zombie.livejournal.com/6450.html','social-zombie-vertical-2012','22.02.2012',{'Обновление':'Блог сообщает о появлении во всех русскоязычных сетях: создаётся Мир; возможны призы Золиан, Золотые лопаты и Зомбаксы. Шансы и стоимость не названы.'},version='исторические русскоязычные социальные сети')
v='https://zombi-obmenka.ucoz.ru/index/materialy2/0-34'
for name,fields in [('Кинолента',{'Создание':'В Кино: 5 мыла и 10 суперклея; ингредиенты определены по названиям файлов пиктограмм, требуют сверки.','Строительство':'Кино и Планетарий. Лимит стоимости 1000 монет.'}),('Бигуди',{'Получение':'Чемоданы туристов.','Строительство':'Купол и Готический склеп; лимит стоимости 1500 монет.'}),('Чёртова спецовка',{'Получение':'Создаётся в Ужасном маяке и Маяке-призраке; рецепт не подписан.','Строительство':'Ужасная мельница, Призрак-мельница; лимит 1000 монет.'}),('Чёртов валенок',{'Получение':'Создаётся в Замке-призраке; рецепт не указан.','Строительство':'Университет-призрак; лимит 1000 монет.'}),('Чёртов тапок',{'Получение':'Создаётся в Замке-призраке; рецепт не указан.','Строительство':'Университет-призрак; лимит 1000 монет.'})]:
 add('materials',name,'',v,'zombi-obmenka-'+name,'редакция страницы неизвестна',fields,version='браузерная игра; конкретная социальная сеть не указана')
s=read('sources')
for x in s:
 if x['number']==67:x['summary']+=' Найден снимок 16.02.2018 с каталогом материалов и ссылками на ЗомбиСити; это копия, не независимое подтверждение. Действующая страница возвращает только заголовок.'
 if x['number']==11:x['summary']+=' Прочитаны отдельные новости от 08.10.2017 и 29.10.2017; сведения об острове и Колесе перенесены, возможное копирование не установлено.'
 if x['number']==60:x['summary']+=' Прочитана страница материалов 1–30, уточнены пять карточек; ссылки и изображения указывают на ZOMBIA, независимость не подтверждена.'
write('sources',s)
